import type { FromRunner, RunnerEvents, RunnerFactory, StageRunner, ToRunner } from "@/lib/three-stage-runner"
import type { StageSize } from "@/lib/three-studio"

/** What the page knows that changes what a scene draws: whether the stage is on screen and motion is reduced. */
type StageView = { inView: boolean; reducedMotion: boolean }

type ThreeStageOptions<State> = {
  /** The `data-slot` of the canvas the stage adds to the host. */
  slot: string
  /** Starts the module worker that serves the runner: `() => new Worker(new URL("./x-worker.js", import.meta.url), { type: "module" })`. */
  worker: () => Worker
  /** Loads the runner to draw on the page where a worker can't: `() => import("./x-runner").then((m) => m.createXRunner)`. */
  runner: () => Promise<RunnerFactory<State>>
  /** The state to draw now; the stage asks again on `refresh()`, when it scrolls in or out and when motion changes. */
  state: (view: StageView) => State
  /** Runs with the host's size, on the first measure and after every resize. */
  onSize?: (size: StageSize) => void
  /** Runs with true once WebGL drew its first frame, and with false when it gave up. */
  onRenderer?: (webgl: boolean) => void
}

type ThreeStage = {
  /** Sends the state again, read from `options.state`. */
  refresh: () => void
  /** Hands the scene a picture drawn on the page, by name. */
  asset: (name: string, canvas: HTMLCanvasElement) => void
  view: () => StageView
  dispose: () => void
}

type Link<State> = {
  setSize: (size: StageSize) => void
  setState: (state: State) => void
  setAsset: (name: string, canvas: HTMLCanvasElement) => void
  dispose: () => void
}

type LinkEvents = RunnerEvents & { failed: () => void }

const quietInputMs = 1200
const inputEvents = ["keydown", "pointerdown", "wheel", "touchstart"]

/** Whether the browser has WebGL at all; a server or a test DOM without it keeps the drawing. */
const supportsThreeStage = () =>
  typeof window !== "undefined" && typeof WebGLRenderingContext !== "undefined" && typeof ResizeObserver === "function"

function makeCanvas(slot: string) {
  const canvas = document.createElement("canvas")
  canvas.dataset.slot = slot
  canvas.setAttribute("aria-hidden", "true")
  return canvas
}

function workerLink<State>(
  canvas: HTMLCanvasElement,
  size: StageSize,
  start: () => Worker,
  events: LinkEvents,
): Link<State> | null {
  if (typeof Worker !== "function" || typeof OffscreenCanvas !== "function") return null
  if (!("transferControlToOffscreen" in canvas) || typeof createImageBitmap !== "function") return null
  let worker: Worker
  try {
    worker = start()
  } catch {
    return null
  }
  let shown = false
  let disposed = false
  const send = (message: ToRunner<State>, transfer: Transferable[] = []) => worker.postMessage(message, transfer)
  worker.addEventListener("message", (event: MessageEvent<FromRunner>) => {
    if (event.data.type === "shown") {
      shown = true
      events.shown()
    } else if (event.data.type === "lost") events.lost()
    else events.failed()
  })
  worker.addEventListener("error", () => (shown ? events.lost() : events.failed()))
  const offscreen = canvas.transferControlToOffscreen()
  send({ type: "start", canvas: offscreen, size }, [offscreen])
  return {
    setSize: (next) => send({ type: "size", size: next }),
    setState: (state) => send({ type: "state", state }),
    setAsset: (name, picture) => {
      void createImageBitmap(picture).then((asset) => {
        if (disposed) asset.close()
        else send({ type: "asset", name, asset }, [asset])
      })
    },
    dispose: () => {
      disposed = true
      send({ type: "dispose" })
    },
  }
}

function pageLink<State>(
  canvas: HTMLCanvasElement,
  size: StageSize,
  load: () => Promise<RunnerFactory<State>>,
  events: LinkEvents,
): Link<State> {
  let runner: StageRunner<State> | null = null
  let disposed = false
  let latest: {
    size: StageSize
    state?: State
    assets: Map<string, HTMLCanvasElement>
  } = { size, assets: new Map() }
  void load().then((create) => {
    if (disposed) return
    runner = create(canvas, latest.size, events)
    if (!runner) {
      events.failed()
      return
    }
    if (latest.state !== undefined) runner.setState(latest.state)
    for (const [name, asset] of latest.assets) runner.setAsset(name, asset)
  }, events.failed)
  return {
    setSize: (next) => {
      latest = { ...latest, size: next }
      runner?.setSize(next)
    },
    setState: (state) => {
      latest = { ...latest, state }
      runner?.setState(state)
    },
    setAsset: (name, asset) => {
      latest.assets.set(name, asset)
      runner?.setAsset(name, asset)
    },
    dispose: () => {
      disposed = true
      runner?.dispose()
    },
  }
}

/**
 * A three.js scene over a drawing in `host`: drawn in a module worker where the browser can (an OffscreenCanvas), on
 * the page otherwise, and started once input has been quiet for a moment after the host is measured. `host` gets
 * `data-renderer="webgl"` once the first frame is drawn, and loses it when WebGL fails or its context is lost, so the
 * drawing shows again.
 */
function createThreeStage<State>(host: HTMLElement, options: ThreeStageOptions<State>): ThreeStage {
  const motion = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : null
  let inView = typeof IntersectionObserver !== "function"
  let size: StageSize | null = null
  const assets = new Map<string, HTMLCanvasElement>()
  let link: Link<State> | null = null
  let canvas: HTMLCanvasElement | null = null
  let triedPage = false
  let ended = false

  const view = (): StageView => ({
    inView,
    reducedMotion: motion?.matches ?? false,
  })
  const refresh = () => link?.setState(options.state(view()))

  const removeCanvas = () => {
    link?.dispose()
    link = null
    canvas?.remove()
    canvas = null
    if (host.dataset.renderer !== undefined) {
      delete host.dataset.renderer
      options.onRenderer?.(false)
    }
  }

  const giveUp = () => {
    removeCanvas()
    ended = true
  }

  const connect = (through: "worker" | "page") => {
    if (!size) return
    canvas = makeCanvas(options.slot)
    host.append(canvas)
    const events: LinkEvents = {
      shown: () => {
        host.dataset.renderer = "webgl"
        options.onRenderer?.(true)
      },
      lost: giveUp,
      failed: () => {
        removeCanvas()
        if (triedPage || ended) giveUp()
        else connect("page")
      },
    }
    if (through === "worker") link = workerLink<State>(canvas, size, options.worker, events)
    if (!link) {
      triedPage = true
      link = pageLink(canvas, size, options.runner, events)
    }
    link.setState(options.state(view()))
    for (const [name, asset] of assets) link.setAsset(name, asset)
  }

  let quietTimer: ReturnType<typeof setTimeout> | undefined
  const startWhenQuiet = () => {
    clearTimeout(quietTimer)
    quietTimer = setTimeout(() => {
      stopWaiting()
      if (typeof requestIdleCallback === "function") requestIdleCallback(() => connectOnce(), { timeout: 1000 })
      else connectOnce()
    }, quietInputMs)
  }
  const stopWaiting = () => {
    clearTimeout(quietTimer)
    for (const name of inputEvents) removeEventListener(name, startWhenQuiet, true)
  }
  const connectOnce = () => {
    if (!ended && !link) connect("worker")
  }
  for (const name of inputEvents) addEventListener(name, startWhenQuiet, { capture: true, passive: true })

  const resize = new ResizeObserver(([entry]) => {
    if (!entry || ended) return
    const { width, height } = entry.contentRect
    const first = size === null
    size = { width, height, pixelRatio: devicePixelRatio || 1 }
    options.onSize?.(size)
    if (link) link.setSize(size)
    else if (first) startWhenQuiet()
  })
  resize.observe(host)

  const visibility =
    typeof IntersectionObserver === "function"
      ? new IntersectionObserver(([entry]) => {
          inView = entry?.isIntersecting ?? true
          refresh()
        })
      : null
  visibility?.observe(host)

  motion?.addEventListener("change", refresh)

  return {
    refresh,
    view,
    asset(name, picture) {
      assets.set(name, picture)
      link?.setAsset(name, picture)
    },
    dispose() {
      ended = true
      stopWaiting()
      resize.disconnect()
      visibility?.disconnect()
      motion?.removeEventListener("change", refresh)
      removeCanvas()
    },
  }
}

export { createThreeStage, supportsThreeStage }
export type { StageView, ThreeStage, ThreeStageOptions }

import type { StageSize } from "@/lib/three-studio"

/** A picture the page draws and hands to the scene by name, such as a record's label. */
type StageAsset = ImageBitmap | HTMLCanvasElement | OffscreenCanvas

/** A three.js scene a runner draws: it draws `State` on request and says while it still moves. */
type StageScene<State> = {
  /** Whether WebGL runs on the CPU, where every frame is costly: the runner then waits for changes to settle. */
  software: boolean
  /** Resolves once the shaders have compiled and the textures are uploaded; it draws nothing before. */
  prepare: () => Promise<void>
  setSize: (size: StageSize) => void
  /** Whether it has what it needs to draw (an asset it waits for); true when left out. */
  ready?: () => boolean
  /** Whether the state still changes on its own, so the runner draws the next frame too. */
  animating: (state: State) => boolean
  render: (state: State) => void
  receive?: (name: string, asset: StageAsset) => void
  dispose: () => void
}

type ToRunner<State> =
  | { type: "start"; canvas: OffscreenCanvas; size: StageSize }
  | { type: "size"; size: StageSize }
  | { type: "state"; state: State }
  | { type: "asset"; name: string; asset: ImageBitmap }
  | { type: "dispose" }

type FromRunner = { type: "shown" } | { type: "unsupported" } | { type: "lost" }

/** `shown` fires after the first frame; `lost` when the WebGL context is gone. */
type RunnerEvents = { shown: () => void; lost: () => void }

type StageRunner<State> = {
  setSize: (size: StageSize) => void
  setState: (state: State) => void
  setAsset: (name: string, asset: StageAsset) => void
  dispose: () => void
}

/** Starts a runner on a canvas: `null` when the canvas has no WebGL. */
type RunnerFactory<State> = (
  canvas: HTMLCanvasElement | OffscreenCanvas,
  size: StageSize,
  events: RunnerEvents,
) => StageRunner<State> | null

const gpuPacing = { settleMs: 0, frameMs: 0 }
const softwarePacing = { settleMs: 150, frameMs: 66 }

function requestFrame(draw: () => void): () => void {
  if (typeof requestAnimationFrame === "function") {
    const frame = requestAnimationFrame(draw)
    return () => cancelAnimationFrame(frame)
  }
  const timer = setTimeout(draw, 16)
  return () => clearTimeout(timer)
}

function after(milliseconds: number, run: () => void): () => void {
  const timer = setTimeout(run, milliseconds)
  return () => clearTimeout(timer)
}

/**
 * Draws `scene` into `canvas` once per change, and every frame while it animates. On a software renderer it waits for
 * changes to settle and draws at most 15 frames a second. `null` when the canvas has no WebGL.
 */
function createStageRunner<State>(
  canvas: HTMLCanvasElement | OffscreenCanvas,
  size: StageSize,
  events: RunnerEvents,
  createScene: (canvas: HTMLCanvasElement | OffscreenCanvas, size: StageSize) => StageScene<State>,
  initial: State,
): StageRunner<State> | null {
  let scene: StageScene<State>
  try {
    scene = createScene(canvas, size)
  } catch {
    return null
  }
  const pacing = scene.software ? softwarePacing : gpuPacing
  let changedAt = 0
  let drawnAt = Number.NEGATIVE_INFINITY
  let state = initial
  let prepared = false
  let cancelPending: (() => void) | null = null
  let shown = false
  let lost = false

  const draw = () => {
    cancelPending = null
    if (lost || !prepared || !(scene.ready?.() ?? true)) return
    scene.render(state)
    drawnAt = performance.now()
    if (!shown) {
      shown = true
      events.shown()
    }
    if (scene.animating(state)) schedule()
  }
  const schedule = () => {
    if (cancelPending !== null) return
    const now = performance.now()
    const settling = scene.animating(state) ? 0 : pacing.settleMs - (now - changedAt)
    const wait = Math.max(settling, pacing.frameMs - (now - drawnAt))
    cancelPending =
      wait > 0
        ? after(wait, () => {
            cancelPending = null
            schedule()
          })
        : requestFrame(draw)
  }

  void scene.prepare().then(
    () => {
      prepared = true
      schedule()
    },
    () => {
      lost = true
      events.lost()
    },
  )

  canvas.addEventListener("webglcontextlost", () => {
    lost = true
    events.lost()
  })

  return {
    setSize(next) {
      scene.setSize(next)
      schedule()
    },
    setState(next) {
      state = next
      changedAt = performance.now()
      schedule()
    },
    setAsset(name, asset) {
      scene.receive?.(name, asset)
      schedule()
    },
    dispose() {
      cancelPending?.()
      lost = true
      scene.dispose()
    },
  }
}

function send(message: FromRunner) {
  self.postMessage(message, { transfer: [] })
}

/** Serves a runner to the page from a worker: the page sends `ToRunner` messages and hears `FromRunner` ones. */
function serveStageRunner<State>(create: RunnerFactory<State>) {
  let runner: StageRunner<State> | null = null
  self.addEventListener("message", (event: MessageEvent<ToRunner<State>>) => {
    const message = event.data
    if (message.type === "start") {
      runner = create(message.canvas, message.size, {
        shown: () => send({ type: "shown" }),
        lost: () => send({ type: "lost" }),
      })
      if (!runner) send({ type: "unsupported" })
      return
    }
    if (!runner) return
    if (message.type === "size") runner.setSize(message.size)
    else if (message.type === "state") runner.setState(message.state)
    else if (message.type === "asset") runner.setAsset(message.name, message.asset)
    else {
      runner.dispose()
      runner = null
      self.close()
    }
  })
}

export { createStageRunner, serveStageRunner }
export type { FromRunner, RunnerEvents, RunnerFactory, StageAsset, StageRunner, StageScene, ToRunner }

import {
  BackSide,
  BoxGeometry,
  Color,
  DoubleSide,
  Mesh,
  MeshBasicMaterial,
  PlaneGeometry,
  PMREMGenerator,
  Scene,
  Texture,
  Vector3,
  type BufferGeometry,
  type Camera,
  type Material,
  type Object3D,
  type WebGLRenderer,
} from "three"

/** The stage's size in CSS pixels and the device pixels per CSS pixel. */
type StageSize = { width: number; height: number; pixelRatio: number }

/** A light panel of the studio: its size, brightness, where it hangs (it faces the middle) and its tint. */
type Softbox = {
  width: number
  height: number
  intensity: number
  at: readonly [number, number, number]
  tint?: number
}

const maxPixelRatio = 2
const softwarePixelRatio = 0.75
const softwareRenderers = /swiftshader|llvmpipe|softpipe|basic render|warp/i

function rendererName(gl: WebGLRenderingContext | WebGL2RenderingContext) {
  const debug = gl.getExtension("WEBGL_debug_renderer_info")
  return String(gl.getParameter(debug ? debug.UNMASKED_RENDERER_WEBGL : gl.RENDERER))
}

/** Whether WebGL runs on the CPU (SwiftShader, llvmpipe, WARP), where every frame is costly. */
const isSoftwareRenderer = (renderer: WebGLRenderer) => softwareRenderers.test(rendererName(renderer.getContext()))

/** Device pixels per CSS pixel to draw at: at most 2, and below 1 on a software renderer. */
const stagePixelRatio = (software: boolean, pixelRatio: number) =>
  software ? softwarePixelRatio : Math.min(maxPixelRatio, pixelRatio)

const darkStudio: readonly Softbox[] = [
  { width: 40, height: 14, intensity: 6, at: [0, 45, 10] },
  { width: 10, height: 60, intensity: 4, at: [-45, 10, 10], tint: 0xfff1e0 },
  { width: 8, height: 50, intensity: 3, at: [45, 15, -10], tint: 0xdfe8ff },
  { width: 60, height: 6, intensity: 1.2, at: [0, 6, 46] },
]

function softboxStudio(softboxes: readonly Softbox[]) {
  const room = new Scene()
  room.add(new Mesh(new BoxGeometry(100, 100, 100), new MeshBasicMaterial({ color: 0x0a0a0c, side: BackSide })))
  for (const { width, height, intensity, at, tint = 0xffffff } of softboxes) {
    const material = new MeshBasicMaterial({
      color: new Color(tint).multiplyScalar(intensity),
      side: DoubleSide,
    })
    const panel = new Mesh(new PlaneGeometry(width, height), material)
    panel.position.copy(new Vector3(...at))
    panel.lookAt(0, 0, 0)
    room.add(panel)
  }
  return room
}

function texturesOf(root: Object3D) {
  const textures = new Set<Texture>()
  root.traverse((object) => {
    if (!(object instanceof Mesh)) return
    const mesh: Mesh = object
    for (const material of Array.isArray(mesh.material) ? mesh.material : [mesh.material]) {
      for (const value of Object.values(material)) if (value instanceof Texture) textures.add(value)
    }
  })
  return textures
}

/** Frees the geometries, materials and textures of every mesh under `root`. */
function disposeAll(root: Object3D) {
  const used = new Set<Material>()
  const geometries = new Set<BufferGeometry>()
  for (const texture of texturesOf(root)) texture.dispose()
  root.traverse((object) => {
    if (!(object instanceof Mesh)) return
    const mesh: Mesh = object
    geometries.add(mesh.geometry)
    for (const material of Array.isArray(mesh.material) ? mesh.material : [mesh.material]) used.add(material)
  })
  for (const geometry of geometries) geometry.dispose()
  for (const material of used) material.dispose()
}

/**
 * A dark studio lit by softboxes, prefiltered for reflections. A room environment washes dark materials grey; this
 * keeps them dark with bright edges. `cubeSize` (256 by default) sets its resolution and memory. Dispose the returned
 * texture with the scene.
 */
function studioEnvironment(renderer: WebGLRenderer, softboxes: readonly Softbox[] = darkStudio, cubeSize?: number) {
  const pmrem = new PMREMGenerator(renderer)
  const studio = softboxStudio(softboxes)
  const environment = pmrem.fromScene(studio, 0.02, 0.1, 100, cubeSize === undefined ? {} : { size: cubeSize })
  disposeAll(studio)
  pmrem.dispose()
  return environment
}

const nextFrame = () =>
  new Promise<void>((resolve) => {
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(() => resolve())
    else setTimeout(resolve, 16)
  })

/**
 * Compiles the scene's shaders off the GPU's main thread, then uploads its textures one per frame, so the first frame
 * doesn't stall the page.
 */
async function prepareScene(renderer: WebGLRenderer, scene: Scene, camera: Camera) {
  await renderer.compileAsync(scene, camera)
  await [...texturesOf(scene)].reduce(
    (uploaded, texture) => uploaded.then(nextFrame).then(() => renderer.initTexture(texture)),
    Promise.resolve(),
  )
  await nextFrame()
}

export { darkStudio, disposeAll, isSoftwareRenderer, prepareScene, stagePixelRatio, studioEnvironment, texturesOf }
export type { Softbox, StageSize }

import { CanvasTexture, RepeatWrapping, SRGBColorSpace, type Texture } from "three"

/** A canvas to draw into: an OffscreenCanvas where there is one (in a worker too), a `<canvas>` otherwise. */
type Surface = HTMLCanvasElement | OffscreenCanvas
type Context2D = CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D
type Draw = (context: Context2D, width: number, height: number) => void

function surface(width: number, height = width): Surface {
  if (typeof OffscreenCanvas === "function") return new OffscreenCanvas(width, height)
  const canvas = document.createElement("canvas")
  canvas.width = width
  canvas.height = height
  return canvas
}

function context2d(canvas: Surface): Context2D | null {
  return typeof OffscreenCanvas === "function" && canvas instanceof OffscreenCanvas
    ? canvas.getContext("2d")
    : canvas.getContext("2d")
}

const isBitmap = (image: unknown): image is ImageBitmap =>
  typeof ImageBitmap === "function" && image instanceof ImageBitmap

/** The same numbers in every browser for a seed, from 0 (inclusive) to 1. */
function seededRandom(seed: number) {
  let state = seed
  return () => {
    state = (state + 0x6d2b79f5) | 0
    let mixed = Math.imul(state ^ (state >>> 15), 1 | state)
    mixed = (mixed + Math.imul(mixed ^ (mixed >>> 7), 61 | mixed)) ^ mixed
    return ((mixed ^ (mixed >>> 14)) >>> 0) / 4294967296
  }
}

/** A texture drawn once on a canvas: square for a number, or `{ width, height }`; `color` marks it as sRGB. */
function canvasTexture(size: number | { width: number; height: number }, draw: Draw, color: boolean) {
  const { width, height } = typeof size === "number" ? { width: size, height: size } : size
  const canvas = surface(width, height)
  const context = context2d(canvas)
  if (context) draw(context, width, height)
  const texture = new CanvasTexture(canvas)
  if (color) texture.colorSpace = SRGBColorSpace
  texture.anisotropy = 8
  return texture
}

function repeating(texture: Texture, times: number, timesY = times) {
  texture.wrapS = RepeatWrapping
  texture.wrapT = RepeatWrapping
  texture.repeat.set(times, timesY)
  return texture
}

/** Grey noise around `base` (0 to 255) by `spread`, with flecks of grain on top when `grain` is set. */
function noise(context: Context2D, size: number, base: number, spread: number, grain: boolean, seed: number) {
  const random = seededRandom(seed)
  const image = context.createImageData(size, size)
  for (let index = 0; index < size * size; index++) {
    const value = base + (random() - 0.5) * spread
    image.data[index * 4] = value
    image.data[index * 4 + 1] = value
    image.data[index * 4 + 2] = value
    image.data[index * 4 + 3] = 255
  }
  context.putImageData(image, 0, 0)
  if (!grain) return
  context.globalAlpha = 0.18
  for (let index = 0; index < size * 3; index++) {
    context.fillStyle = random() > 0.5 ? "#fff" : "#000"
    context.beginPath()
    context.arc(random() * size, random() * size, 0.6 + random() * 2.2, 0, Math.PI * 2)
    context.fill()
  }
  context.globalAlpha = 1
}

export { canvasTexture, context2d, isBitmap, noise, repeating, seededRandom, surface }
export type { Context2D, Draw, Surface }
